// ===========================================================================
//  RUN SETTINGS — the only node you normally touch.
// ===========================================================================

// Which source lists to verify. Separate tags with | . Examples:
//   'example_list'             one list
//   'list_a|list_b'            two lists at once
const SOURCES = 'example_list';

// true  = only companies whose `sources` holds this tag and nothing else. A
//         company that also arrived through another list is skipped — those
//         lists carry their own campaign history, and mixing them makes the
//         numbers unreadable.
// false = any company carrying the tag, however many others it also carries.
const ONLY_THIS_SOURCE = true;

// true  = skip any company that already has an outreach_log row. Those were
//         mailed in an earlier campaign and most already carry a real
//         email_status (sent / bounced / replied), which is better evidence
//         than a verifier result and costs nothing.
const SKIP_CONTACTED = true;

// How many companies to draw at random from what is left. 0 = no cap, take
// everything. Every unchecked address of a drawn company comes along, so the
// address count lands a little above this number.
const COMPANIES = 300;

// ===========================================================================

// Interpolated into SQL below, so keep the tags to safe characters.
const tags = SOURCES.split('|').map(t => t.trim()).filter(Boolean);
if (!tags.length) throw new Error('SOURCES is empty');
for (const t of tags) {
  if (!/^[A-Za-z0-9_()-]+$/.test(t)) throw new Error(`bad source tag: ${t}`);
}
if (!Number.isInteger(COMPANIES) || COMPANIES < 0) {
  throw new Error('COMPANIES must be a whole number, 0 or more');
}

return [{
  json: {
    sources: tags.join('|'),
    only_this_source: ONLY_THIS_SOURCE,
    skip_contacted: SKIP_CONTACTED,
    no_cap: COMPANIES === 0,
    company_limit: COMPANIES === 0 ? 'all' : String(COMPANIES),
  },
}];

// Turn a verifier response into the values contacts.verification_status
// allows ('valid' / 'not valid' -- there is a CHECK constraint).
//
// Keep this mapping identical across runs so results stay comparable over
// time. catch_all and unknown count as valid: low bounce risk, not confirmed.
const map = {
  ok:         { status: 'valid',     detail: 'Deliverable' },
  catch_all:  { status: 'valid',     detail: 'Catch-all domain - mailbox not individually confirmed, low bounce risk' },
  unknown:    { status: 'valid',     detail: 'Unconfirmed - mail server gave no definitive answer (common for large providers), low bounce risk' },
  invalid:    { status: 'not valid', detail: 'Invalid mailbox - will bounce' },
  disposable: { status: 'not valid', detail: 'Disposable/temporary address' },
};

// Match the API response back to its contact row by email, not by position --
// the verifier echoes the address back, and that survives retries.
const byEmail = new Map(
  $('Execute a SQL query').all().map(i => [String(i.json.email).toLowerCase(), i.json])
);

const today = new Date().toISOString().slice(0, 10);
const out = [];

for (const item of $input.all()) {
  const resp = item.json;
  const hit  = map[resp.result];

  // No recognised verdict means an API error, an exhausted key, or a result
  // value the verifier did not use before. Stop rather than write a guess:
  // rows already saved keep their verification_checked_at, so re-running picks
  // up exactly where this stopped and never pays for the same address twice.
  if (!hit) {
    throw new Error(
      'Verifier gave no usable result for ' + (resp.email || '(no email in response)') +
      ' -- result=' + JSON.stringify(resp.result) +
      ' error=' + JSON.stringify(resp.error)
    );
  }

  const src = byEmail.get(String(resp.email || '').toLowerCase());
  if (!src) {
    throw new Error('Response for ' + resp.email + ' does not match any row from the SQL query');
  }

  out.push({ json: {
    id: src.id,
    email: src.email,
    verification_status: hit.status,
    verification_details: hit.detail,
    verification_source: 'millionverifier',
    verification_checked_at: today,
  }});
}

return out;
